def test_exact_frequency_map(run, x):
    answer = run(x)
    expected = {}
    for values in x['d'].values():
        for value in values:
            expected[value] = expected.get(value, 0) + 1
    assert answer == expected

def test_counter_frequency_map(run, x):
    from collections import Counter
    answer = run(x)
    flattened = [value for values in x['d'].values() for value in values]
    assert answer == dict(Counter(flattened))

def test_all_input_values_have_counts(run, x):
    answer = run(x)
    flattened = [value for values in x['d'].values() for value in values]
    assert isinstance(answer, dict)
    assert all(answer.get(value) == flattened.count(value) for value in set(flattened))

def test_no_unseen_keys(run, x):
    answer = run(x)
    flattened = [value for values in x['d'].values() for value in values]
    assert isinstance(answer, dict)
    assert all(key in flattened for key in answer)

def test_counts_are_exact(run, x):
    answer = run(x)
    flattened = [value for values in x['d'].values() for value in values]
    assert isinstance(answer, dict)
    assert all(count == sum(item == key for item in flattened) for key, count in answer.items())

def test_keys_match_distinct_values(run, x):
    answer = run(x)
    flattened = [value for values in x['d'].values() for value in values]
    assert isinstance(answer, dict)
    assert set(answer) == set(flattened)

def test_total_count_matches_elements(run, x):
    answer = run(x)
    flattened = [value for values in x['d'].values() for value in values]
    assert isinstance(answer, dict)
    assert sum(answer.values()) == len(flattened)

def test_positive_integer_counts(run, x):
    answer = run(x)
    assert isinstance(answer, dict)
    assert all(isinstance(count, int) and count > 0 for count in answer.values())

def test_empty_lists_contribute_nothing(run, x):
    answer = run(x)
    expected = {}
    for values in x['d'].values():
        for value in values:
            expected[value] = expected.setdefault(value, 0) + 1
    assert answer == expected

def test_frequency_map_from_nested_loops(run, x):
    answer = run(x)
    expected = {}
    for key in x['d']:
        for value in x['d'][key]:
            if value in expected:
                expected[value] += 1
            else:
                expected[value] = 1
    assert answer == expected
